import * as THREE from "three";

const AMP = 1.1; // swell height: crest to trough is twice this
const K = 0.5; // swell wavenumber along x (wavelength ≈ 12.6)

// Static swell. The board rides the front face at x = z = 0, where the surface is close to planar.
export function swell(x, z) {
  const phase = K * x + Math.PI + 0.22 * Math.sin(0.45 * z + 0.5) + 0.12 * Math.sin(1.1 * z);
  return AMP * (Math.sin(phase) + 0.25 * Math.sin(2 * phase + 0.6));
}

// Small chop that flows backwards past the board (towards -x). This is what sells the ride.
export function ripples(x, z, t) {
  return (
    0.035 * Math.sin(3.2 * x + 1.8 * z + 4.2 * t) +
    0.025 * Math.sin(5.1 * x - 0.9 * z + 5.6 * t + 1.0) +
    0.018 * Math.sin(2.3 * x + 2.4 * z + 3.3 * t + 2.0)
  );
}

export function surfaceHeight(x, z, t) {
  return swell(x, z) + ripples(x, z, t);
}

const DEEP = new THREE.Color(0x0b3c5d);
const MID = new THREE.Color(0x1f7ea1);
const LIGHT = new THREE.Color(0x63cbd9);
const FOAM = new THREE.Color(0xf5fbff);

export function createOcean() {
  const geometry = new THREE.PlaneGeometry(50, 70, 200, 140);
  geometry.rotateX(-Math.PI / 2);
  geometry.translate(0, 0, -20); // z from -55 (horizon) to 15 (behind the camera)

  const position = geometry.attributes.position;
  const count = position.count;
  const baseHeight = new Float32Array(count);
  const foamBase = new Float32Array(count);

  // The swell never changes, so its height and foam mask are computed once.
  for (let i = 0; i < count; i++) {
    const x = position.getX(i);
    const z = position.getZ(i);
    const h = swell(x, z);
    const slope = (swell(x + 0.05, z) - swell(x - 0.05, z)) / 0.1;
    baseHeight[i] = h;
    foamBase[i] =
      THREE.MathUtils.smoothstep(h, 0.45 * AMP, 0.85 * AMP) +
      0.5 * THREE.MathUtils.smoothstep(-slope, 0.2, 0.5);
  }

  const colors = new Float32Array(count * 3);
  geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  const material = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.3, metalness: 0 });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;

  const color = new THREE.Color();

  function update(t) {
    for (let i = 0; i < count; i++) {
      const x = position.getX(i);
      const z = position.getZ(i);
      const rip = ripples(x, z, t);
      const h = baseHeight[i] + rip;
      position.setY(i, h);

      // Deep water to teal to light crest, with moving foam streaks where the ripples catch the face.
      const depth = THREE.MathUtils.clamp((h + AMP) / (2 * AMP), 0, 1);
      color.lerpColors(DEEP, MID, depth).lerp(LIGHT, depth * depth * depth * 0.7);
      color.lerp(FOAM, THREE.MathUtils.clamp(foamBase[i] * (1 + 4 * rip), 0, 1));
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    position.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
    geometry.computeVertexNormals();
  }

  update(0);
  return { mesh, update };
}

import * as THREE from "three";
import { swell } from "./ocean.js";

const NOSE_X = 1.3;
const TAIL_X = -1.3;
const WIDEST_X = -0.15;
const HALF_WIDTH = 0.27;
const TAIL_HALF_WIDTH = 0.1;
const FIN_X = -0.95;
const DECK_ABOVE_SWELL = 0.1; // deck height above the swell line when the board is at rest
const EPS = 0.02;

const UP = new THREE.Vector3(0, 1, 0);
const X_AXIS = new THREE.Vector3(1, 0, 0);
const normal = new THREE.Vector3();
const forward = new THREE.Vector3();
const side = new THREE.Vector3();
const basis = new THREE.Matrix4();
const yaw = new THREE.Quaternion();
const roll = new THREE.Quaternion();

// Half-width of the outline at x: a rounded nose and a squarish tail.
function halfWidth(x) {
  if (x >= WIDEST_X) {
    const t = (x - WIDEST_X) / (NOSE_X - WIDEST_X);
    return HALF_WIDTH * Math.pow(1 - Math.pow(t, 2.4), 0.55);
  }
  const t = (WIDEST_X - x) / (WIDEST_X - TAIL_X);
  return TAIL_HALF_WIDTH + (HALF_WIDTH - TAIL_HALF_WIDTH) * Math.pow(1 - Math.pow(t, 3), 0.4);
}

// Outline in the XY plane (x along the length, y across the width).
function outlineShape(steps = 80) {
  const xAt = (i) => TAIL_X + ((NOSE_X - TAIL_X) * i) / steps;
  const points = [];
  for (let i = 0; i <= steps; i++) points.push(new THREE.Vector2(xAt(i), -halfWidth(xAt(i))));
  for (let i = steps - 1; i >= 0; i--) points.push(new THREE.Vector2(xAt(i), halfWidth(xAt(i))));
  return new THREE.Shape(points);
}

export function createSurfboard() {
  const board = new THREE.Group();

  const deckGeometry = new THREE.ExtrudeGeometry(outlineShape(), {
    depth: 0.07,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 3,
    curveSegments: 8,
  });
  deckGeometry.rotateX(Math.PI / 2); // length along x, width along z, thickness down y
  deckGeometry.computeBoundingBox();
  deckGeometry.translate(0, -deckGeometry.boundingBox.max.y, 0); // deck top at y = 0

  const finGeometry = new THREE.ExtrudeGeometry(
    new THREE.Shape([new THREE.Vector2(-0.14, -0.06), new THREE.Vector2(0.12, -0.06), new THREE.Vector2(0, -0.27)]),
    { depth: 0.025, bevelEnabled: false }
  );
  finGeometry.translate(0, 0, -0.0125);

  const deck = new THREE.Mesh(deckGeometry, new THREE.MeshStandardMaterial({ color: 0xff6f4a, roughness: 0.4 }));
  const fin = new THREE.Mesh(finGeometry, new THREE.MeshStandardMaterial({ color: 0x2b3a48, roughness: 0.4 }));
  fin.position.x = FIN_X;

  board.add(deck, fin);
  return board;
}

// Lays the board on the swell at x = z = 0, with a little carving yaw and roll on top.
export function poseSurfboard(board, t) {
  const slopeX = (swell(EPS, 0) - swell(-EPS, 0)) / (2 * EPS);
  const slopeZ = (swell(0, EPS) - swell(0, -EPS)) / (2 * EPS);
  normal.set(-slopeX, 1, -slopeZ).normalize();
  forward.copy(X_AXIS).addScaledVector(normal, -normal.x).normalize();
  side.crossVectors(forward, normal);
  board.quaternion.setFromRotationMatrix(basis.makeBasis(forward, normal, side));
  board.quaternion.multiply(yaw.setFromAxisAngle(UP, 0.07 * Math.sin(0.6 * t)));
  board.quaternion.multiply(roll.setFromAxisAngle(X_AXIS, 0.05 * Math.sin(1.1 * t + 1)));
  board.position.set(0, swell(0, 0) + DECK_ABOVE_SWELL + 0.03 * Math.sin(1.3 * t), 0);
}

import * as THREE from "three";

const COLORS = {
  white: 0xf4f1ea,
  wing: 0xbdb9ad,
  wingTip: 0x3a4048,
  bill: 0xe8ad4a,
  pouch: 0xf0953a,
  foot: 0xe8862e,
  tail: 0x9fa39a,
  eye: 0x1c2026,
};

const UP = new THREE.Vector3(0, 1, 0);
const SPHERE = new THREE.SphereGeometry(1, 24, 16);
const materials = new Map();

function material(color) {
  if (!materials.has(color)) {
    materials.set(color, new THREE.MeshStandardMaterial({ color, roughness: 0.55, side: THREE.DoubleSide }));
  }
  return materials.get(color);
}

function ellipsoid(center, radii, color, rotationZ = 0) {
  const mesh = new THREE.Mesh(SPHERE, material(color));
  mesh.position.set(...center);
  mesh.scale.set(...radii);
  mesh.rotation.z = rotationZ;
  return mesh;
}

// Sweeps an elliptical cross-section along a smooth curve. radii(u) returns [rx, ry] for u in 0..1.
function tubeMesh(points, radii, color, samples = 24, sides = 14) {
  const curve = new THREE.CatmullRomCurve3(points.map((p) => new THREE.Vector3(...p)));
  const position = [];
  const index = [];
  const side = new THREE.Vector3();
  const up = new THREE.Vector3();

  for (let i = 0; i <= samples; i++) {
    const u = i / samples;
    const center = curve.getPointAt(u);
    const tangent = curve.getTangentAt(u);
    side.crossVectors(tangent, UP);
    if (side.lengthSq() < 1e-6) side.set(0, 0, 1);
    side.normalize();
    up.crossVectors(side, tangent).normalize();

    const [rx, ry] = radii(u);
    for (let j = 0; j < sides; j++) {
      const a = (j / sides) * Math.PI * 2;
      const c = Math.cos(a) * rx;
      const s = Math.sin(a) * ry;
      position.push(
        center.x + side.x * c + up.x * s,
        center.y + side.y * c + up.y * s,
        center.z + side.z * c + up.z * s
      );
    }
  }

  for (let i = 0; i < samples; i++) {
    for (let j = 0; j < sides; j++) {
      const a = i * sides + j;
      const b = i * sides + ((j + 1) % sides);
      const c = (i + 1) * sides + j;
      const d = (i + 1) * sides + ((j + 1) % sides);
      index.push(a, c, b, b, c, d);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(position, 3));
  geometry.setIndex(index);
  geometry.computeVertexNormals();
  return new THREE.Mesh(geometry, material(color));
}

// Flat feather-like plate in the XY plane, thickness along z.
function feather(points, depth) {
  const geometry = new THREE.ExtrudeGeometry(
    new THREE.Shape(points.map(([x, y]) => new THREE.Vector2(x, y))),
    { depth, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.008, bevelSegments: 2, curveSegments: 12 }
  );
  geometry.translate(0, 0, -depth / 2);
  return geometry;
}

const WING_OUTLINE = new THREE.SplineCurve(
  [[-0.1, 0], [0.08, 0.05], [0.14, 0.3], [0.13, 0.6], [0.07, 0.86], [0, 1], [-0.08, 0.9], [-0.13, 0.62], [-0.15, 0.3], [-0.1, 0]].map(
    ([x, y]) => new THREE.Vector2(x, y)
  )
).getPoints(48);

const wingGeometry = feather(WING_OUTLINE.map((p) => [p.x, p.y]), 0.03);
const wingTipGeometry = feather(
  [[-0.13, 0.62], [0.12, 0.6], [0.07, 0.86], [0, 1], [-0.08, 0.9]],
  0.045
);

function createWing(side) {
  const pivot = new THREE.Group();
  pivot.position.set(0.05, 1.0, side * 0.18);
  pivot.add(new THREE.Mesh(wingGeometry, material(COLORS.wing)), new THREE.Mesh(wingTipGeometry, material(COLORS.wingTip)));
  return pivot;
}

const aimDirection = new THREE.Vector3();

// Points a wing (which extends along its local +y) in the given direction.
function aimWing(pivot, x, y, z) {
  pivot.quaternion.setFromUnitVectors(UP, aimDirection.set(x, y, z).normalize());
}

// Procedural pelican standing on a board, facing +x. The feet stay on the deck;
// the upper body sways over them and the wings flail for balance.
export function createPelican() {
  const root = new THREE.Group();
  const upper = new THREE.Group();
  root.add(upper);

  for (const z of [-0.1, 0.1]) {
    root.add(tubeMesh([[0, 0.62, z], [0.1, 0.36, z], [0.03, 0.1, z]], () => [0.035, 0.035], COLORS.foot, 12, 8));
    root.add(ellipsoid([0.08, 0.03, z], [0.2, 0.03, 0.12], COLORS.foot));
  }

  upper.add(ellipsoid([0, 0.82, 0], [0.46, 0.27, 0.26], COLORS.white, 0.16)); // body
  upper.add(ellipsoid([-0.5, 0.76, 0], [0.16, 0.05, 0.13], COLORS.tail, -0.35)); // tail
  upper.add(
    tubeMesh(
      [[0.3, 0.95, 0], [0.45, 1.16, 0], [0.52, 1.4, 0], [0.64, 1.6, 0], [0.78, 1.7, 0]],
      (u) => {
        const r = 0.15 - 0.06 * u;
        return [r, r * 0.9];
      },
      COLORS.white
    )
  );
  upper.add(ellipsoid([0.82, 1.74, 0], [0.15, 0.13, 0.125], COLORS.white)); // head
  upper.add(ellipsoid([0.9, 1.79, 0.11], [0.03, 0.03, 0.03], COLORS.eye)); // eye
  upper.add(
    tubeMesh(
      [[0.9, 1.76, 0], [1.1, 1.74, 0], [1.3, 1.69, 0], [1.42, 1.62, 0]],
      (u) => [0.05 - 0.02 * u, 0.03 - 0.015 * u],
      COLORS.bill
    )
  ); // bill
  upper.add(ellipsoid([1.1, 1.56, 0], [0.22, 0.12, 0.1], COLORS.pouch, -0.15)); // pouch

  const nearWing = createWing(1);
  const farWing = createWing(-1);
  upper.add(nearWing, farWing);

  function update(t) {
    upper.rotation.z = 0.05 * Math.sin(1.3 * t);
    upper.rotation.x = 0.04 * Math.sin(1.7 * t + 0.5);

    const flap = Math.sin(2.4 * t);
    aimWing(nearWing, 0.75, 0.6 + 0.12 * flap, 0.35);
    aimWing(farWing, -0.55, 0.85 - 0.1 * flap, -0.3);
  }

  return { root, update };
}

import * as THREE from "three";
import { surfaceHeight } from "./ocean.js";

const COUNT = 320;
const GRAVITY = 6;
const EMIT_RATE = 90; // droplets per second

function dropletTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext("2d");
  const gradient = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  gradient.addColorStop(0, "rgba(255,255,255,1)");
  gradient.addColorStop(0.45, "rgba(255,255,255,0.9)");
  gradient.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(canvas);
}

// Pool of droplets thrown off the tail and rails and flung back over the wake.
export function createSpray() {
  const positions = new Float32Array(COUNT * 3).fill(-1000);
  const velocities = new Float32Array(COUNT * 3);
  const life = new Float32Array(COUNT);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  const material = new THREE.PointsMaterial({
    map: dropletTexture(),
    size: 0.12,
    sizeAttenuation: true,
    transparent: true,
    depthWrite: false,
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;

  const local = new THREE.Vector3();
  let cursor = 0;
  let pending = 0;

  function spawn(board) {
    const i = cursor;
    cursor = (cursor + 1) % COUNT;

    if (Math.random() < 0.5) {
      local.set(-1.25, -0.04, (Math.random() - 0.5) * 0.4);
    } else {
      local.set(-1.1 + Math.random() * 1.2, -0.04, Math.random() < 0.5 ? -0.27 : 0.27);
    }
    board.localToWorld(local);

    positions.set([local.x, local.y, local.z], i * 3);
    velocities.set([-(1 + Math.random() * 1.6), 1.2 + Math.random() * 1.8, (Math.random() - 0.5) * 1.2], i * 3);
    life[i] = 0.9 + Math.random() * 0.5;
  }

  // The board's world matrix must be current before calling this.
  function update(dt, t, board) {
    pending += EMIT_RATE * dt;
    while (pending >= 1) {
      pending -= 1;
      spawn(board);
    }

    for (let i = 0; i < COUNT; i++) {
      if (life[i] <= 0) continue;
      const k = i * 3;
      life[i] -= dt;
      velocities[k + 1] -= GRAVITY * dt;
      positions[k] += velocities[k] * dt;
      positions[k + 1] += velocities[k + 1] * dt;
      positions[k + 2] += velocities[k + 2] * dt;
      if (life[i] <= 0 || positions[k + 1] < surfaceHeight(positions[k], positions[k + 2], t)) {
        life[i] = 0;
        positions[k + 1] = -1000;
      }
    }
    geometry.attributes.position.needsUpdate = true;
  }

  return { points, update };
}

import * as THREE from "three";
import { createOcean } from "./ocean.js";
import { createPelican } from "./pelican.js";
import { createSpray } from "./spray.js";
import { createSurfboard, poseSurfboard } from "./surfboard.js";

const HORIZON = 0xcfe9f5;
const ZENITH = 0x3f86d6;
const CAMERA_TARGET = new THREE.Vector3(0.3, 0.8, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
// Fog colour matches the sky's horizon so the far edge of the water dissolves into it.
scene.fog = new THREE.Fog(HORIZON, 14, 50);
scene.add(createSky());

const key = new THREE.DirectionalLight(0xfff1dc, 2.2);
key.position.set(-4, 9, 6);
scene.add(key, new THREE.HemisphereLight(0xdff4ff, 0x1d5a7a, 1.2));

const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 1000);

const ocean = createOcean();
const board = createSurfboard();
const pelican = createPelican();
const spray = createSpray();
board.add(pelican.root);
scene.add(ocean.mesh, board, spray.points);

function createSky() {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      zenith: { value: new THREE.Color(ZENITH) },
      horizon: { value: new THREE.Color(HORIZON) },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      uniform vec3 zenith;
      uniform vec3 horizon;
      varying vec3 vDir;
      void main() {
        float h = clamp(normalize(vDir).y, 0.0, 1.0);
        gl_FragColor = vec4(mix(horizon, zenith, pow(h, 0.5)), 1.0);
        #include <colorspace_fragment>
      }`,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(400, 32, 16), material);
  sky.renderOrder = -1;
  return sky;
}

function resize() {
  const { innerWidth: width, innerHeight: height } = window;
  renderer.setSize(width, height);
  camera.aspect = width / height;
  camera.fov = camera.aspect < 1 ? 40 / Math.sqrt(camera.aspect) : 40;
  camera.updateProjectionMatrix();
}
window.addEventListener("resize", resize);
resize();

let last = 0;
function frame(ms) {
  const t = ms / 1000;
  const dt = Math.min(t - last, 0.05);
  last = t;

  ocean.update(t);
  poseSurfboard(board, t);
  board.updateMatrixWorld(true);
  pelican.update(t);
  spray.update(dt, t, board);

  camera.position.set(-0.5 + 0.2 * Math.sin(0.12 * t), 1.45 + 0.08 * Math.sin(0.31 * t), 5.6);
  camera.lookAt(CAMERA_TARGET);
  renderer.render(scene, camera);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

